    // (2) Assign the control input queue from the VirtIOSerial struct
    vq = vser->c_ivq;

    // (3) Check if the queue is ready
    if (!virtio_queue_ready(vq)) {
        return 0;
    }

    // (4) Attempt to pop an element from the queue
    if (!virtqueue_pop(vq, &elem)) {
        return 0;
    }

    // (5) Copy the input buffer to the queue element's IO vector
    memcpy(elem.in_sg[0].iov_base, buf, len);

    // (6) Push the modified element back into the queue
    virtqueue_push(vq, &elem, len);

    // (7) Notify the device about the update
    virtio_notify(VIRTIO_DEVICE(vser), vq);

    // (8) Return the length of the data sent
    return len;
}
